					d="M49.1185 0.607398C50.5283 -0.206636 52.2665 -0.200104 53.6767 0.61289L53.6822 0.607398L77.1102 14.1282C78.5202 14.9451 79.3892 16.4529 79.3892 18.0823V42.334L100.225 54.3775C101.643 55.1937 102.515 56.7018 102.515 58.3316V112.404C102.514 114.033 101.648 115.542 100.231 116.358L100.225 116.352L53.3856 143.388C52.1483 144.099 50.6534 144.193 49.3547 143.657L48.811 143.388L25.4709 129.857C24.0192 129.017 23.1542 127.502 23.1542 125.872V101.621L2.31828 89.5772C0.900259 88.761 0.0283203 87.2529 0.0283203 85.6231V31.5505C0.0296715 29.9213 0.895318 28.4124 2.31278 27.5966L49.1185 0.607398Z"
