					d="M46.5 9C53.4036 9 59 14.5964 59 21.5C59 28.3017 53.5675 33.8343 46.8047 33.9961L59.3789 47.1982C60.7432 48.6307 59.7282 51 57.75 51H25.25C25.1479 51 25.0477 50.9907 24.9492 50.9775C24.6345 50.9915 24.3181 51 24 51H21C9.40202 51 0 41.598 0 30C0 18.402 9.40202 9 21 9H46.5ZM21 17.5C14.0964 17.5 8.5 23.0964 8.5 30C8.5 36.9036 14.0964 42.5 21 42.5C27.9036 42.5 33.5 36.9036 33.5 30C33.5 23.0964 27.9036 17.5 21 17.5Z"
